// A) range windows downward
bool ok(TreeNode* r, long long lo, long long hi){
    if(!r) return true;
    if (r->val <= lo || r->val >= hi) return false;
    return ok(r->left, lo, r->val) && ok(r->right, r->val, hi);
}
// B) inorder prev-pointer
TreeNode* prevP = nullptr;
bool inorder(TreeNode* r){
    if(!r) return true;
    if (!inorder(r->left)) return false;
    if (prevP && prevP->val >= r->val) return false;
    prevP = r;
    return inorder(r->right);
}

TreeNode* deleteNode(TreeNode* root, int key){
    if(!root) return nullptr;
    if (key < root->val) root->left = deleteNode(root->left, key);
    else if (key > root->val) root->right = deleteNode(root->right, key);
    else {
        if (!root->right) { TreeNode* l = root->left; delete root; return l; }
        if (!root->left)  { TreeNode* r = root->right; delete root; return r; }
        TreeNode* succ = root->right;                 // min of right
        while (succ->left) succ = succ->left;
        root->val = succ->val;                        // copy up
        root->right = deleteNode(root->right, succ->val); // remove duplicate below
    }
    return root;
}

