class BSTIterator:
    def __init__(self, root):
        self.st = []
        self._push_left(root)
    def _push_left(self, r):
        while r: self.st.append(r); r = r.left
    def next(self):
        n = self.st.pop(); self._push_left(n.right)
        return n.val
    def hasNext(self):
        return bool(self.st)
